 package/contents/ui/main.qml          |  4 +-
 plugin/passwordsmodel.cpp             | 39 +++++++++++++---
 plugin/passwordsmodel.h               | 10 +++++
 6 files changed, 144 insertions(+), 6 deletions(-)
