                 }

                 PasswordFilterModel {
diff --git a/plugin/passwordsmodel.cpp b/plugin/passwordsmodel.cpp
index f62a9ee..4d104c3 100644
--- a/plugin/passwordsmodel.cpp
+++ b/plugin/passwordsmodel.cpp
@@ -6,6 +6,8 @@
 #include "passwordprovider.h"
 #include "otpprovider.h"

+#include <KShell>
+
 #include <QDebug>
 #include <QPointer>

@@ -78,11 +80,7 @@ PasswordsModel::PasswordsModel(QObject *parent)
     : QAbstractItemModel(parent)
     , mWatcher(this)
 {
-    if (qEnvironmentVariableIsSet(passwordStoreDir)) {
-        mPassStore = QDir(QString::fromUtf8(qgetenv(passwordStoreDir)));
-    } else {
-        mPassStore = QDir(QStringLiteral("%1/.password-store").arg(QDir::homePath()));
-    }
+    updatePassStore();

     // FIXME: Try to figure out what has actually changed and update the model
     // accordingly instead of reseting it
@@ -93,6 +91,34 @@ PasswordsModel::PasswordsModel(QObject *parent)

 PasswordsModel::~PasswordsModel() = default;

+QString PasswordsModel::passwordStoreDirectory() const
+{
+    return mPassStoreDirectory;
+}
+
+void PasswordsModel::setPasswordStoreDirectory(const QString &directory)
+{
+    if (mPassStoreDirectory == directory) {
+        return;
+    }
+
+    mPassStoreDirectory = directory;
+    updatePassStore();
+    populate();
+    Q_EMIT passwordStoreDirectoryChanged();
+}
+
+void PasswordsModel::updatePassStore()
+{
+    if (!mPassStoreDirectory.isEmpty()) {
+        mPassStore = QDir(KShell::tildeExpand(mPassStoreDirectory));
+    } else if (qEnvironmentVariableIsSet(passwordStoreDir)) {
+        mPassStore = QDir(QString::fromUtf8(qgetenv(passwordStoreDir)));
+    } else {
+        mPassStore = QDir(QStringLiteral("%1/.password-store").arg(QDir::homePath()));
+    }
+}
+
 PasswordsModel::Node *PasswordsModel::node(const QModelIndex &index)
 {
     return static_cast<Node *>(index.internalPointer());
@@ -197,6 +223,9 @@ QVariant PasswordsModel::data(const QModelIndex &index, int role) const
 void PasswordsModel::populate()
 {
     beginResetModel();
+    if (const auto watched = mWatcher.directories(); !watched.isEmpty()) {
+        mWatcher.removePaths(watched);
+    }
     mRoot = std::make_unique<Node>();
     mRoot->name = mPassStore.absolutePath();
     populateDir(mPassStore, mRoot.get());
