     void populate();
     void populateDir(const QDir &dir, Node *parent);

@@ -58,6 +67,7 @@ private:

     QFileSystemWatcher mWatcher;
     QDir mPassStore;
+    QString mPassStoreDirectory;

     std::unique_ptr<Node> mRoot;
 };
